      'Nhập "Email", "Tên hiển thị", chọn vai trò "Hỗ trợ", "Thời hạn quyền" là "Không giới hạn", nhập lý do, chạm "Gửi lời mời".',
      'Mở tab "Lời mời · …"; mời thử email của một thành viên đang hoạt động.',
      'Người được mời: mở thư mời, vào portal, chọn "Link qua email", nhập đúng email đó, chạm "Gửi link đăng nhập" rồi mở link.',
      'Admin: tải lại tab "Thành viên · …"; mở "Nhật ký thao tác", nhóm "Nhân sự".',
