      'Tab "Lời mời" có email, vai trò, "Người mời" và "Hết hạn" sau 7 ngày; KPI "Lời mời đang chờ" tăng 1; mời email đã là thành viên báo "Email này đã là thành viên portal."',
      'Thư "… mời bạn vào Child Life · Vận hành" ghi vai trò; mở link vào thẳng portal, thẻ người dùng ghi "Hỗ trợ" và thanh bên đúng quyền Hỗ trợ.',
      'Người mới ở tab "Thành viên" với trạng thái "Hoạt động", lời mời biến khỏi tab "Lời mời"; nhật ký có "Mời thành viên" (kèm lý do) và "Nhận lời mời vào portal".',
